const updateFieldDefinition = `-- name: UpdateFieldDefinition :one
UPDATE field_definition SET
    label                     = COALESCE($1,                     label),
    description               = COALESCE($2,               description),
    options                   = COALESCE($3,                   options),
    required                  = COALESCE($4,                  required),
    searchable                = COALESCE($5,                searchable),
    applies_to                = COALESCE($6,                applies_to),
    read_capability           = COALESCE($7,           read_capability),
    write_capability          = COALESCE($8,          write_capability),
    display_order             = COALESCE($9,             display_order),
    display_group             = COALESCE($10,             display_group),
    status                    = COALESCE($11,                    status),
    deprecated_replacement_id = COALESCE($12, deprecated_replacement_id),
    -- default_value needs a CLEAR path, which COALESCE cannot express:
    -- passing NULL means "leave it alone" everywhere else in this
    -- statement, so "remove the default" would be unsayable. The
    -- explicit boolean makes removal a deliberate act rather than an
    -- ambiguity in the absence of a value.
    default_value             = CASE WHEN $13::BOOLEAN THEN NULL
                                     ELSE COALESCE($14, default_value) END,
    updated_at                = NOW(),
    updated_by_user_ref       = $15
WHERE id = $16
RETURNING id, code, label, description, type, options, required, searchable,
          applies_to, read_capability, write_capability,
          display_order, display_group, status,
          deprecated_replacement_id, origin_server_id,
          created_at, updated_at, created_by_user_ref, updated_by_user_ref,
          subject_kind, extraction_source, extraction_mode, default_value
`

type UpdateFieldDefinitionParams struct {
	Label                   *string
	Description             *string
	Options                 []byte
	Required                *bool
	Searchable              *bool
	AppliesTo               []int64
	ReadCapability          *string
	WriteCapability         *string
	DisplayOrder            *int32
	DisplayGroup            *string
	Status                  *string
	DeprecatedReplacementID pgtype.UUID
	ClearDefault            bool
	DefaultValue            []byte
	UpdatedByUserRef        *int64
	ID                      pgtype.UUID
}

// COALESCE pattern: NULL args keep current value. `applies_to` is a
// non-nullable column, so it always replaces when the caller
// intends to update it; the handler decides whether to pass NULL or
// an explicit empty array.
func (q *Queries) UpdateFieldDefinition(ctx context.Context, arg UpdateFieldDefinitionParams) (FieldDefinition, error) {
	row := q.db.QueryRow(ctx, updateFieldDefinition,
		arg.Label,
		arg.Description,
		arg.Options,
		arg.Required,
		arg.Searchable,
		arg.AppliesTo,
		arg.ReadCapability,
		arg.WriteCapability,
		arg.DisplayOrder,
		arg.DisplayGroup,
		arg.Status,
		arg.DeprecatedReplacementID,
		arg.ClearDefault,
		arg.DefaultValue,
		arg.UpdatedByUserRef,
		arg.ID,
	)
	var i FieldDefinition
	err := row.Scan(
		&i.ID,
		&i.Code,
		&i.Label,
		&i.Description,
		&i.Type,
		&i.Options,
		&i.Required,
		&i.Searchable,
		&i.AppliesTo,
		&i.ReadCapability,
		&i.WriteCapability,
		&i.DisplayOrder,
		&i.DisplayGroup,
		&i.Status,
		&i.DeprecatedReplacementID,
		&i.OriginServerID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CreatedByUserRef,
		&i.UpdatedByUserRef,
		&i.SubjectKind,
		&i.ExtractionSource,
		&i.ExtractionMode,
		&i.DefaultValue,
	)
	return i, err
}

